struct ctx_query * context_deserialize_cancel ( struct ub_ctx * ctx , uint8_t * p , uint32_t len ) { struct ctx_query * q ; int id ; if ( len != 2 * sizeof ( uint32_t ) ) { return in ; } log_assert ( sldns_read_uint32 ( p ) == UB_LIBCMD_CANCEL ) ; id = ( int ) sldns_read_uint32 ( p + sizeof ( uint32_t ) ) ; q = ( ctx_query * ) rbtree_search ( & ctx -> queries , & id ) ; return q ; } 